// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadCaveatBrush = makeLoadFont('CaveatBrush');

// Library: @remotion/paths — native evolvePath for stroke-order whiteboard drawing

const { fontFamily } = loadCaveatBrush();



export type WhiteboardAnimationProps = Record<string, any>;

const easeDraw = { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.quad) } as const;

const makeStickFigure = (scale: number, ox: number, oy: number, straighter: boolean = false) => {
  const t = 110 * scale;
  const headR = 35 * scale;
  const hC = oy - headR;
  const eyeY = hC - 5 * scale;
  const eyeX = 12 * scale;
  const smileY1 = hC + 10 * scale;
  const smileY2 = hC + 20 * scale;
  const smileX = 15 * scale;

  const legSpread = straighter ? 20 * scale : 35 * scale;
  const footSpread = straighter ? 35 * scale : 50 * scale;
  const armSpread = straighter ? 30 * scale : 45 * scale;

  return [
    `M ${ox} ${oy} L ${ox} ${oy + t}`, // Torso
    `M ${ox} ${oy} A ${headR} ${headR} 0 1 1 ${ox} ${oy - headR * 2} A ${headR} ${headR} 0 1 1 ${ox} ${oy}`, // Head ON TOP of torso
    `M ${ox} ${oy + t * 0.25} L ${ox - armSpread} ${oy + t * 0.7}`, // L Arm from shoulder
    `M ${ox} ${oy + t * 0.25} L ${ox + armSpread} ${oy + t * 0.7}`, // R Arm from shoulder
    `M ${ox} ${oy + t} L ${ox - legSpread} ${oy + t + 90 * scale} L ${ox - footSpread} ${oy + t + 90 * scale}`, // L Leg from hip
    `M ${ox} ${oy + t} L ${ox + legSpread} ${oy + t + 90 * scale} L ${ox + footSpread} ${oy + t + 90 * scale}`, // R Leg from hip
    // Face
    `M ${ox - eyeX} ${eyeY} L ${ox - eyeX} ${eyeY + 0.1}`,
    `M ${ox + eyeX} ${eyeY} L ${ox + eyeX} ${eyeY + 0.1}`,
    `M ${ox - smileX} ${smileY1} Q ${ox} ${smileY2} ${ox + smileX} ${smileY1}`
  ].join(" ");
};

const makeBox = (w: number, h: number) => `M 0 0 L ${w} 0 L ${w} ${h} L 0 ${h} Z`;

const FigureComp = ({ x, groundY, scale, straighter, progress, s, ink }: { x: number; groundY: number; scale: number; straighter: boolean; progress: number; s: number; ink: string }) => {
  if (progress === 0) return null;
  const width = 400 * s;
  const height = 500 * s;
  const centerX = width / 2;
  const feetY = 400 * s;
  const oy = feetY - 200 * scale * s;

  const path = makeStickFigure(scale * s, centerX, oy, straighter);
  const evolution = evolvePath(progress, path);

  return (
    <svg width={width} height={height} style={{ position: "absolute", left: (x * s) - (width / 2), top: (groundY * s) - feetY, overflow: "visible" }}>
      <path d={path} stroke={ink} strokeWidth={6 * s} fill="none" strokeLinecap="round" strokeLinejoin="round" strokeDasharray={evolution.strokeDasharray} strokeDashoffset={evolution.strokeDashoffset} style={{ transition: "none" }} />
    </svg>
  );
};

const LabelComp = ({ text, x, y, w, h, progress, s, ink }: { text: string; x: number; y: number; w: number; h: number; progress: number; s: number; ink: string }) => {
  if (progress === 0) return null;
  const boxProgress = interpolate(progress, [0, 0.5], [0, 1], { extrapolateRight: "clamp" });
  const textProgress = interpolate(progress, [0.5, 1], [0, 1], { extrapolateLeft: "clamp" });
  const boxPath = makeBox(w * s, h * s);
  const evolution = evolvePath(boxProgress, boxPath);

  return (
    <div style={{ position: "absolute", left: (x - w / 2) * s, top: (y - h / 2) * s, width: w * s, height: h * s, display: "flex", justifyContent: "center", alignItems: "center" }}>
      <svg width={w * s} height={h * s} style={{ position: "absolute", left: 0, top: 0, overflow: "visible" }}>
        <path d={boxPath} stroke={ink} strokeWidth={5 * s} fill="none" strokeDasharray={evolution.strokeDasharray} strokeDashoffset={evolution.strokeDashoffset} strokeLinecap="round" strokeLinejoin="round" style={{ transition: "none" }} />
      </svg>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", zIndex: 10, fontFamily, color: ink, fontSize: 48 * s, fontWeight: "bold", lineHeight: 1.2 }}>
        {text.split("\n").map((line, i) => (
          <div key={i} style={{ clipPath: `inset(0 ${100 - textProgress * 100}% 0 0)`, whiteSpace: "nowrap" }}>
            {line}
          </div>
        ))}
      </div>
    </div>
  );
};

const ArrowComp = ({ sx, sy, cx, cy, ex, ey, progress, s, color }: { sx: number; sy: number; cx: number; cy: number; ex: number; ey: number; progress: number; s: number; color: string }) => {
  if (progress === 0) return null;

  // Split overall drawing progress: 0% to 80% draws the shaft, 80% to 100% draws the arrowhead.
  const shaftProgress = interpolate(progress, [0, 0.8], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const headProgress = interpolate(progress, [0.8, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const tx = ex - cx;
  const ty = ey - cy;
  const angle = Math.atan2(ty, tx);
  const headLen = 30; // Raw size scaled with s
  const a1 = angle - Math.PI / 6;
  const a2 = angle + Math.PI / 6;

  const h1x = ex - headLen * Math.cos(a1);
  const h1y = ey - headLen * Math.sin(a1);
  const h2x = ex - headLen * Math.cos(a2);
  const h2y = ey - headLen * Math.sin(a2);

  const shaftPath = `M ${sx * s} ${sy * s} Q ${cx * s} ${cy * s} ${ex * s} ${ey * s}`;
  // Drawing the tip back-and-forth like a natural sketch
  const headPath = `M ${h1x * s} ${h1y * s} L ${ex * s} ${ey * s} L ${h2x * s} ${h2y * s}`;

  const evolutionShaft = evolvePath(shaftProgress, shaftPath);
  const evolutionHead = evolvePath(headProgress, headPath);

  return (
    <svg width={1920 * s} height={1080 * s} style={{ position: "absolute", left: 0, top: 0, overflow: "visible" }}>
      {shaftProgress > 0 && (
        <path
          d={shaftPath}
          stroke={color}
          strokeWidth={6 * s}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={evolutionShaft.strokeDasharray}
          strokeDashoffset={evolutionShaft.strokeDashoffset}
          style={{ transition: "none" }}
        />
      )}
      {headProgress > 0 && (
        <path
          d={headPath}
          stroke={color}
          strokeWidth={6 * s}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={evolutionHead.strokeDasharray}
          strokeDashoffset={evolutionHead.strokeDashoffset}
          style={{ transition: "none" }}
        />
      )}
    </svg>
  );
};

const WhiteboardAnimation: React.FC<WhiteboardAnimationProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 15,
  accentColor = "#2FA090",
  highlightColor = "#F5C518",
  inkColor = "#1A1A1A",
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const pFooter = interpolate(frame, [0, 15], [0, 1], easeDraw);
  const pFig = interpolate(frame, [15, 45], [0, 1], easeDraw);
  const pLab1 = interpolate(frame, [45, 75], [0, 1], easeDraw);
  const pArrow1 = interpolate(frame, [96, 120], [0, 1], easeDraw);
  const pArrow2 = interpolate(frame, [120, 144], [0, 1], easeDraw);
  
  const eraseLab = interpolate(frame, [150, 165], [0, 1], easeDraw);
  const pLabSwapped = interpolate(frame, [175, 205], [0, 1], easeDraw);
  
  const pSame = interpolate(frame, [270, 300], [0, 1], easeDraw);
  const pHighlighter = interpolate(frame, [342, 360], [0, 1], easeDraw);

  const zoom = interpolate(frame, [210, 270], [1, 1.15], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  const lab1Progress = frame < 150 ? pLab1 : Math.max(0, 1 - eraseLab);
  const arrow1Progress = frame < 150 ? pArrow1 : Math.max(0, 1 - eraseLab);
  const arrow2Progress = frame < 150 ? pArrow2 : Math.max(0, 1 - eraseLab);
  const labSwappedProgress = pLabSwapped;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div style={{ width: "100%", height: "100%", filter: "url(#marker-boil)", transform: `scale(${zoom})`, transformOrigin: "center 60%" }}>
        
        {pFooter > 0 && (
          <div style={{ position: "absolute", left: 60 * s, bottom: 40 * s, fontFamily, fontSize: 24 * s, color: "#C9C9C9", clipPath: `inset(0 ${100 - pFooter * 100}% 0 0)`, letterSpacing: 2 * s, whiteSpace: "nowrap" }}>
            MARK KENTWELL | FLOWZONE
          </div>
        )}

        <FigureComp x={550} groundY={750} scale={1} straighter={false} progress={pFig} s={s} ink={inkColor} />
        <FigureComp x={1370} groundY={750} scale={1} straighter={false} progress={pFig} s={s} ink={inkColor} />

        <LabelComp text="LOWEST&#10;AI USER" x={550} y={220} w={420} h={160} progress={lab1Progress} s={s} ink={inkColor} />
        <LabelComp text="HIGHEST&#10;PRODUCER" x={1370} y={220} w={420} h={160} progress={lab1Progress} s={s} ink={inkColor} />

        <LabelComp text="HIGHEST&#10;PRODUCER" x={550} y={220} w={420} h={160} progress={labSwappedProgress} s={s} ink={inkColor} />
        <LabelComp text="LOWEST&#10;AI USER" x={1370} y={220} w={420} h={160} progress={labSwappedProgress} s={s} ink={inkColor} />

        <ArrowComp sx={770} sy={180} cx={960} cy={40} ex={1150} ey={180} progress={arrow1Progress} s={s} color={accentColor} />
        <ArrowComp sx={1150} sy={260} cx={960} cy={400} ex={770} ey={260} progress={arrow2Progress} s={s} color={accentColor} />

        <div style={{ position: "absolute", left: 0, top: 860 * s, width: 1920 * s, display: "flex", justifyContent: "center", alignItems: "center" }}>
          <div style={{ position: "relative", display: "flex", justifyContent: "center", alignItems: "center" }}>
            {pHighlighter > 0 && (
              <div style={{ position: "absolute", left: "-2%", width: "104%", height: 110 * s, backgroundColor: highlightColor, clipPath: `inset(0 ${100 - pHighlighter * 100}% 0 0)`, borderRadius: 12 * s }} />
            )}
            {pSame > 0 && (
              <div style={{ fontFamily, fontSize: 100 * s, color: inkColor, fontWeight: "bold", letterSpacing: 4 * s, clipPath: `inset(0 ${100 - pSame * 100}% 0 0)`, whiteSpace: "nowrap", zIndex: 10 }}>
                SAME PERSON.
              </div>
            )}
          </div>
        </div>

      </div>

      <svg width="0" height="0" style={{ position: "absolute" }}>
        <filter id="marker-boil">
          <feTurbulence type="fractalNoise" baseFrequency="0.04" numOctaves="3" result="noise" />
          <feDisplacementMap in="SourceGraphic" in2="noise" scale={1.5 * s} xChannelSelector="R" yChannelSelector="G" />
        </filter>
      </svg>
    </AbsoluteFill>
  );
};

export default WhiteboardAnimation;